export class ContinuousPdfViewer{
 constructor({container,pagesRoot=container,pageLabel,onPage,error,maxWidth=1100}){this.container=container;this.pagesRoot=pagesRoot;this.pageLabel=pageLabel;this.onPage=onPage;this.error=error;this.maxWidth=maxWidth;this.pdf=null;this.zoom=1;this.current=1;this.sections=[];this.rendering=new Map();this.scrollTimer=0;this.onScroll=()=>{clearTimeout(this.scrollTimer);this.scrollTimer=setTimeout(()=>this.track(),60)};container.addEventListener('scroll',this.onScroll,{passive:true});}
 async open(pdf,{page=1,zoom=1}={}){this.destroyDocument();this.pdf=pdf;this.zoom=zoom;this.current=Math.max(1,Math.min(pdf.numPages,page));const first=await pdf.getPage(1),v=first.getViewport({scale:1});this.ratio=v.width/v.height;this.pagesRoot.replaceChildren();this.sections=Array.from({length:pdf.numPages},(_,i)=>{const section=document.createElement('section');section.className='continuous-pdf-page';section.dataset.page=String(i+1);section.setAttribute('aria-label',`第 ${i+1} 页`);const badge=document.createElement('span');badge.className='continuous-page-number';badge.textContent=String(i+1);const canvas=document.createElement('canvas');canvas.hidden=true;section.append(canvas,badge);this.pagesRoot.append(section);return section});this.layout();this.observer=new IntersectionObserver(entries=>{for(const entry of entries){entry.target.dataset.visible=entry.isIntersecting?'true':'false';if(entry.isIntersecting)this.render(entry.target);else this.release(entry.target)}},{root:this.container,rootMargin:'1200px 0px'});this.sections.forEach(s=>this.observer.observe(s));requestAnimationFrame(()=>this.go(this.current,false));this.updateLabel();}
 layout(){if(!this.pdf)return;const width=Math.max(180,Math.min(this.maxWidth,this.container.clientWidth-28))*this.zoom;for(const section of this.sections){section.style.width=width+'px';section.style.height=width/this.ratio+'px';}}
 async render(section){const number=+section.dataset.page,key=`${number}:${this.zoom}:${this.container.clientWidth}`;if(section.dataset.renderKey===key||this.rendering.has(number))return;const run=(async()=>{try{const page=await this.pdf.getPage(number);if(!this.pdf)return;const natural=page.getViewport({scale:1}),cssWidth=Math.max(180,Math.min(this.maxWidth,this.container.clientWidth-28))*this.zoom,viewport=page.getViewport({scale:cssWidth/natural.width});let dpr=Math.min(devicePixelRatio||1,2);dpr=Math.min(dpr,Math.sqrt(16000000/(viewport.width*viewport.height)));const canvas=section.querySelector('canvas');canvas.width=Math.max(1,Math.floor(viewport.width*dpr));canvas.height=Math.max(1,Math.floor(viewport.height*dpr));canvas.style.width=viewport.width+'px';canvas.style.height=viewport.height+'px';section.style.height=viewport.height+'px';canvas.hidden=false;await page.render({canvasContext:canvas.getContext('2d'),viewport,transform:dpr===1?null:[dpr,0,0,dpr,0,0]}).promise;section.dataset.renderKey=key;if(section.dataset.visible==='false')this.release(section);}catch(e){if(e?.name!=='RenderingCancelledException'){section.classList.add('render-error');this.error?.(e)}}finally{this.rendering.delete(number)}})();this.rendering.set(number,run);await run;}
 release(section){if(this.rendering.has(+section.dataset.page))return;const canvas=section.querySelector('canvas');canvas.width=1;canvas.height=1;canvas.hidden=true;delete section.dataset.renderKey;}
 track(){if(!this.sections.length)return;const top=this.container.getBoundingClientRect().top+12;let best=this.sections[0],distance=Infinity;for(const section of this.sections){const r=section.getBoundingClientRect(),d=Math.abs(r.top-top);if(d<distance){distance=d;best=section}if(r.top>top&&d>distance)break}const next=+best.dataset.page;if(next!==this.current){this.current=next;this.updateLabel();this.onPage?.(next)}}
 updateLabel(){if(this.pageLabel&&this.pdf)this.pageLabel.textContent=`${this.current} / ${this.pdf.numPages}`;}
 go(number,smooth=true){if(!this.pdf)return;this.current=Math.max(1,Math.min(this.pdf.numPages,number));this.sections[this.current-1]?.scrollIntoView({block:'start',behavior:smooth?'smooth':'instant'});this.updateLabel();this.onPage?.(this.current);}
 setZoom(value){this.zoom=value;for(const section of this.sections){delete section.dataset.renderKey;const canvas=section.querySelector('canvas');canvas.hidden=true;}this.layout();for(const section of this.sections){const r=section.getBoundingClientRect(),root=this.container.getBoundingClientRect();if(r.bottom>=root.top-1200&&r.top<=root.bottom+1200)this.render(section)}this.go(this.current,false);}
 resize(){if(!this.pdf)return;for(const section of this.sections){delete section.dataset.renderKey;section.querySelector('canvas').hidden=true;}this.layout();this.go(this.current,false);this.sections.slice(Math.max(0,this.current-2),this.current+2).forEach(s=>this.render(s));}
 destroyDocument(){this.observer?.disconnect();this.observer=null;this.rendering.clear();this.sections=[];this.pagesRoot.replaceChildren();this.pdf=null;}
 destroy(){this.destroyDocument();this.container.removeEventListener('scroll',this.onScroll);clearTimeout(this.scrollTimer);}
}
